/* Customer documentation only. L pairs English and Spanish copy. */
(() => {
const L=(en,es)=>({en,es});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C=(text,file='CONFIG.LUA')=>`<div class="code-block"><div class="code-header"><span>${file}</span><button class="copy" data-copy><span data-icon="copy"></span><span data-i18n="copy">Copy</span></button></div><pre><code>${esc(text)}</code></pre></div>`;
const T=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const N=(title,body,kind='info')=>`<div class="callout ${kind}"><span data-icon="${kind==='info'?'info':'alert'}"></span><div><strong>${title}</strong><p>${body}</p></div></div>`;
const D=(file,label)=>`<a class="download" href="downloads/${file}" download><span data-icon="download"></span>${label}</a>`;
const S=(id,enTitle,esTitle,enBody,esBody)=>({id,title:L(enTitle,esTitle),body:L(enBody,esBody)});
const page=(id,icon,group,enTitle,esTitle,enLead,esLead,sections)=>({id,icon,group,title:L(enTitle,esTitle),lead:L(enLead,esLead),sections});
const cfg=`BlastBB.Integration = {
    Inventory = 'auto',
    InventoryResource = nil,
    Target = 'blast_3d',
    TargetResource = nil,
}`;
const telemetry=`BlastBB.Telemetry = {
    Enabled = false,
    SendServerIdentity = false,
}`;
const start=`ensure ox_lib
ensure oxmysql
# Start your framework and inventory here, if used.
ensure ox_inventory
ensure blast_boombox`;
const items=[
['portable_speaker','Portable Speaker','4.5 kg','Handheld speaker with a handle and animated rings.','Portátil con asa y anillos animados.'],
['cylinder_speaker','Cylinder Speaker','850 g','Compact cylindrical speaker that can be carried in one hand.','Altavoz cilíndrico compacto que puedes llevar en una mano.'],
['backpack_speaker','Backpack Speaker','3.2 kg','Wearable speaker. The backpack can remain equipped inside a vehicle.','Altavoz de mochila. Puede permanecer equipado dentro de un vehículo.'],
['sphere_speaker','Sphere Speaker','2.2 kg','Spherical portable with an animated driver and illuminated halo.','Portátil esférico con cono animado y halo iluminado.'],
['capsule_speaker','Sound Capsule','6.2 kg','A flower-shaped speaker with six opening petals.','Altavoz con forma de flor y seis pétalos que se abren.'],
['display_speaker','Display Speaker','7.8 kg','A raised screen displays the cover and metadata of the current track.','Una pantalla elevada muestra la portada y los datos de la canción.'],
['cooler_speaker','Cooler Speaker','18 kg','An opening cooler speaker with an illuminated driver array.','Neverita que se abre y muestra sus altavoces iluminados.'],
['event_speaker','Event Speaker','25 kg','The largest audio profile, with a deployable tripod and transport options.','El perfil de audio más grande, con trípode desplegable y opciones de transporte.']
];
const cards=(lang)=>`<div class="product-grid">${items.map(([id,name,weight,en,es])=>`<div class="speaker-card"><div class="speaker-image"><img src="assets/items/${id}.png" alt="${name}" loading="lazy" width="170" height="155"></div><h3>${name}</h3><code>${id}</code><p>${lang==='en'?en:es}</p><div class="model-spec"><span>${weight}</span><span>${lang==='en'?'Included model':'Modelo incluido'}</span></div></div>`).join('')}</div>`;
const inventoryTables=(lang)=>T([lang==='en'?'Item identifier':'Identificador',lang==='en'?'Inventory label':'Nombre',lang==='en'?'Weight':'Peso'],[...items.map(i=>[`<code>${i[0]}</code>`,i[1],i[2]]),['<code>radiocar</code>','Car Radio','1.2 kg']]);
const inventoryTabs=`<div class="tabs" role="tablist" aria-label="Inventory"><button class="tab" role="tab" id="inv-ox" data-inventory="ox" aria-selected="true" aria-controls="inventory-panel" tabindex="0">ox_inventory</button><button class="tab" role="tab" id="inv-qb" data-inventory="qb" aria-selected="false" aria-controls="inventory-panel" tabindex="-1">qb-inventory</button><button class="tab" role="tab" id="inv-qs" data-inventory="qs" aria-selected="false" aria-controls="inventory-panel" tabindex="-1">qs-inventory</button><button class="tab" role="tab" id="inv-esx" data-inventory="esx" aria-selected="false" aria-controls="inventory-panel" tabindex="-1">Native ESX</button></div><div id="inventory-panel" role="tabpanel" aria-labelledby="inv-ox"></div>`;
window.INVENTORY_GUIDES={
ox:L(`<ol><li>Merge <code>INSTALL/ox-items.lua</code> into the existing table in <code>ox_inventory/data/items.lua</code>.</li><li>Copy the PNGs from <code>INSTALL/images/</code> into <code>ox_inventory/web/images/</code>, or the image folder configured by your fork.</li><li>Keep <code>consume = 0</code> and the included client exports: Blast removes the item after a confirmed placement.</li><li>Restart the inventory, then <code>blast_boombox</code>.</li></ol>${D('ox-items.lua','Download item definitions')}${C(`['portable_speaker'] = {
    label = 'Portable Speaker', weight = 4500,
    stack = false, close = true, consume = 0,
    client = {
        export = 'blast_boombox.useBoombox',
        image = 'portable_speaker.png'
    }
},`,'OX_INVENTORY/DATA/ITEMS.LUA')}`,`<ol><li>Integra <code>INSTALL/ox-items.lua</code> en la tabla existente de <code>ox_inventory/data/items.lua</code>.</li><li>Copia los PNG de <code>INSTALL/images/</code> a <code>ox_inventory/web/images/</code>, o a la carpeta de imágenes que use tu fork.</li><li>Conserva <code>consume = 0</code> y los exports incluidos: Blast retira el ítem al confirmar la colocación.</li><li>Reinicia el inventario y después <code>blast_boombox</code>.</li></ol>${D('ox-items.lua','Descargar definiciones')}${C(`['portable_speaker'] = {
    label = 'Portable Speaker', weight = 4500,
    stack = false, close = true, consume = 0,
    client = {
        export = 'blast_boombox.useBoombox',
        image = 'portable_speaker.png'
    }
},`,'OX_INVENTORY/DATA/ITEMS.LUA')}`),
qb:L(`<p>With automatic registration enabled, supported QB versions register missing definitions through <code>qb-core:AddItems</code> and register usable handlers. Existing entries are kept.</p><p>For older versions, merge the bundled definitions into your item catalog, usually <code>qb-core/shared/items.lua</code>. Copy icons into your inventory's configured image folder, usually <code>qb-inventory/html/images/</code>.</p>${D('qb-items.lua','Download QB definitions')}${N('Version-specific paths','Inventory forks may use a different catalog or image folder. Use the paths documented by your installed inventory.')}`,`<p>Con el registro automático activado, las versiones compatibles de QB añaden las definiciones que faltan mediante <code>qb-core:AddItems</code> y registran los utilizables. Se conservan las entradas existentes.</p><p>En versiones antiguas, integra las definiciones en tu catálogo de ítems, normalmente <code>qb-core/shared/items.lua</code>. Copia las imágenes a la carpeta de tu inventario, normalmente <code>qb-inventory/html/images/</code>.</p>${D('qb-items.lua','Descargar definiciones QB')}${N('Rutas según la versión','Los forks pueden usar otro catálogo o carpeta de imágenes. Sigue las rutas de tu inventario instalado.')}`),
qs:L(`<p>Merge <code>INSTALL/qs-items.lua</code> into your Quasar item catalog. Copy the icons into the image folder used by your version. Definitions must exist before players can receive the items.</p><p>Blast registers usable handlers through the inventory's public API. Do not add another handler that consumes the same item.</p>${D('qs-items.lua','Download Quasar definitions')}`,`<p>Integra <code>INSTALL/qs-items.lua</code> en el catálogo de Quasar. Copia los iconos a la carpeta de imágenes de tu versión. Las definiciones deben existir antes de dar los ítems a los jugadores.</p><p>Blast registra los utilizables mediante la API pública del inventario. No añadas otro manejador que consuma el mismo ítem.</p>${D('qs-items.lua','Descargar definiciones Quasar')}`),
esx:L(`<p>Supported native ESX versions add missing definitions with <code>ESX.AddItems</code>. For older versions, import the included item SQL once. This SQL defines inventory items; it is separate from Blast's automatically created data tables.</p><p>Copy the item icons into the image directory of your inventory UI. Native ESX is not selected when ESX declares a custom inventory.</p>${D('esx-items.sql','Download ESX item SQL')}`,`<p>Las versiones compatibles de ESX nativo añaden las definiciones que faltan con <code>ESX.AddItems</code>. En versiones antiguas, importa una vez el SQL de ítems incluido. Este SQL define los objetos del inventario; es independiente de las tablas de datos que crea Blast.</p><p>Copia los iconos a la carpeta de imágenes de la interfaz de inventario. No se selecciona ESX nativo cuando ESX declara un inventario personalizado.</p>${D('esx-items.sql','Descargar SQL de ítems ESX')}`)
};
window.DOCS=[
page('overview','book','start','Blast Boombox','Blast Boombox','Music that belongs in the world. Install the resource, place a speaker and make it part of your server.','Música dentro del mundo. Instala el recurso, coloca un speaker y adáptalo a tu servidor.',[
S('start','Start here','Empieza aquí',`<div class="cards"><a class="card" href="#installation"><span data-icon="download"></span><strong>Install Blast Boombox</strong><p>Dependencies, startup order, database and administrator access.</p></a><a class="card" href="#inventory"><span data-icon="box"></span><strong>Add the inventory items</strong><p>Definitions and transparent icons for your inventory.</p></a><a class="card" href="#speakers"><span data-icon="speaker"></span><strong>Explore the speakers</strong><p>Eight models, placement, carrying and animated features.</p></a><a class="card" href="#admin"><span data-icon="settings"></span><strong>Configure your server</strong><p>Colors, audio, device limits and vehicle restrictions.</p></a></div>`,`<div class="cards"><a class="card" href="#installation"><span data-icon="download"></span><strong>Instala Blast Boombox</strong><p>Dependencias, orden de inicio, base de datos y acceso de administrador.</p></a><a class="card" href="#inventory"><span data-icon="box"></span><strong>Añade los ítems</strong><p>Definiciones e iconos transparentes para tu inventario.</p></a><a class="card" href="#speakers"><span data-icon="speaker"></span><strong>Conoce los speakers</strong><p>Ocho modelos, colocación, transporte y funciones animadas.</p></a><a class="card" href="#admin"><span data-icon="settings"></span><strong>Configura tu servidor</strong><p>Colores, audio, límites y restricciones de vehículos.</p></a></div>`),
S('included','What is included','Qué incluye','<p>Eight custom speaker models, RadioCar, music search, playlists, an automatic queue, synchronized channels, spatial audio and lyrics when available. A built-in 3D interaction system lets the resource work without an external target.</p>','<p>Ocho modelos propios de speaker, RadioCar, buscador de música, playlists, cola automática, canales sincronizados, sonido espacial y letras cuando estén disponibles. El sistema de interacción 3D integrado permite usar el recurso sin un target externo.</p>'),
S('requirements','Framework and integrations','Framework e integraciones','<p>The core can run standalone with <code>ox_lib</code> and <code>oxmysql</code>. ESX, QBCore and Qbox are optional. Inventory workflows use the supported adapters or a custom bridge.</p><p>These guides cover version <strong>0.5.0</strong>. Confirm compatibility with the specific versions and forks installed on your server.</p>','<p>El núcleo puede funcionar standalone con <code>ox_lib</code> y <code>oxmysql</code>. ESX, QBCore y Qbox son opcionales. Los flujos de inventario usan los adaptadores compatibles o un bridge personalizado.</p><p>Estas guías cubren la versión <strong>0.5.0</strong>. Comprueba la compatibilidad con las versiones y forks de tu servidor.</p>')]),
page('installation','download','start','Installation','Instalación','Add the resource, register the items and configure your server in game. Blast creates its data tables at startup.','Añade el recurso, registra los ítems y configura tu servidor dentro del juego. Blast crea sus tablas de datos al iniciar.',[
S('dependencies','1. Dependencies','1. Dependencias',T(['Resource','Required','Purpose'],[['<a href="https://docs.fivem.net/docs/server-manual/setting-up-a-server/" target="_blank" rel="noopener">FXServer / OneSync</a>','Yes','Networked devices and player synchronization.'],['<code>ox_lib</code>','Yes','Callbacks, UI helpers and notifications.'],['<code>oxmysql</code>','Yes','Playlists, devices, settings and preferences.'],['An inventory','For item workflows','Place speakers and install RadioCar using items.'],['ESX / QBCore / Qbox','Optional','Framework and inventory integration.'],['<code>ox_target</code> / <code>qb-target</code>','Optional','External interaction adapters. The built-in 3D target is self-contained.']])+N('Music search is integrated','No Python process or separate catalog resource is required.'),T(['Recurso','Obligatorio','Función'],[['<a href="https://docs.fivem.net/docs/server-manual/setting-up-a-server/" target="_blank" rel="noopener">FXServer / OneSync</a>','Sí','Dispositivos en red y sincronización entre jugadores.'],['<code>ox_lib</code>','Sí','Callbacks, ayudas de interfaz y notificaciones.'],['<code>oxmysql</code>','Sí','Playlists, dispositivos, ajustes y preferencias.'],['Un inventario','Para usar ítems','Colocar speakers e instalar RadioCar mediante objetos.'],['ESX / QBCore / Qbox','Opcional','Integración de framework e inventario.'],['<code>ox_target</code> / <code>qb-target</code>','Opcional','Adaptadores externos. El target 3D integrado funciona por sí solo.']])+N('El buscador está integrado','No requiere un proceso de Python ni un recurso de catálogo separado.')),
S('resource','2. Resource and startup order','2. Recurso y orden de inicio',`<p>Copy the complete <code>blast_boombox</code> folder into your resources directory, for example <code>resources/[blast]/blast_boombox</code>. Keep the resource name: the inventory exports reference it.</p><p>Start dependencies, framework and inventory before Blast. This example uses ox_inventory; replace that line with your own inventory.</p>${C(start,'SERVER.CFG')}${N('OneSync','Ensure OneSync is enabled in your server configuration. The SQL connection belongs in your oxmysql/server setup.')}`,`<p>Copia la carpeta completa <code>blast_boombox</code> a tus recursos, por ejemplo <code>resources/[blast]/blast_boombox</code>. Conserva su nombre: los exports del inventario lo usan.</p><p>Inicia las dependencias, el framework y el inventario antes de Blast. Este ejemplo usa ox_inventory; sustituye esa línea por tu inventario.</p>${C(start,'SERVER.CFG')}${N('OneSync','Comprueba que OneSync esté activado. La conexión SQL se configura en oxmysql o en tu servidor.')}`),
S('database','3. Database','3. Base de datos','<p>Blast creates its own tables automatically on startup. You do not need a table-creation SQL file. The database account must have permission to create and read/write tables.</p><p>An optional <code>INSTALL/esx-items.sql</code> file is for inventory item definitions on older native ESX versions, not Blast data storage.</p>','<p>Blast crea sus tablas al iniciar. No necesitas importar un SQL de creación de tablas. La cuenta de base de datos debe poder crear tablas, leer y escribir.</p><p>El archivo opcional <code>INSTALL/esx-items.sql</code> registra ítems en versiones antiguas de ESX nativo; no crea las tablas de datos de Blast.</p>'),
S('items','4. Inventory items','4. Ítems del inventario','<p>Install the definitions for your inventory and copy the PNG icons. Follow the dedicated <a href="#inventory">inventory guide</a> for exact files and exports.</p>','<p>Instala las definiciones de tu inventario y copia los PNG. Sigue la <a href="#inventory">guía de inventario</a> para ver los archivos y exports.</p>'),
S('target','5. Choose the interaction system','5. Elige la interacción',`<p>Set <code>Target = 'blast_3d'</code> in <code>config.lua</code> to use the included target without ox_target or blast_common. The current development configuration selects <code>ox_target</code>; check this setting before starting your installation.</p>${C(cfg)}<p>See <a href="#configuration">configuration</a> for the other adapters.</p>`,`<p>Pon <code>Target = 'blast_3d'</code> en <code>config.lua</code> para usar el target incluido sin ox_target ni blast_common. La configuración actual de desarrollo selecciona <code>ox_target</code>; revisa este ajuste al instalar.</p>${C(cfg)}<p>Consulta <a href="#configuration">configuración</a> para los demás adaptadores.</p>`),
S('admin','6. Administrator access','6. Acceso de administrador',`<p>Grant the default ACE to your administrator group. The player must already belong to that group.</p>${C('add_ace group.admin blast_boombox.admin allow','SERVER.CFG')}<p>Open <code>/boomboxadmin</code> in game. For custom permissions, see <a href="#configuration/permissions">the permission adapter</a>.</p>`,`<p>Concede la ACE al grupo administrador. El jugador debe pertenecer a ese grupo.</p>${C('add_ace group.admin blast_boombox.admin allow','SERVER.CFG')}<p>Abre <code>/boomboxadmin</code> dentro del juego. Para permisos personalizados, consulta <a href="#configuration/permissions">el adaptador de permisos</a>.</p>`),
S('language','7. Language and server settings','7. Idioma y ajustes','<p>Open the admin panel and select the language under Server. English is the initial language on a fresh settings database. Previously saved settings take precedence.</p><p>Choose limits, colors, audio and vehicle policies in game. <code>config.lua</code> is reserved for installation integrations, permissions, item identifiers and support-report controls.</p>','<p>Abre el panel y selecciona el idioma en Servidor. En una base de ajustes nueva, el idioma inicial es inglés. Los ajustes guardados anteriormente tienen prioridad.</p><p>Configura límites, colores, audio y políticas de vehículos dentro del juego. <code>config.lua</code> contiene integraciones, permisos, identificadores de ítems y controles de informes de soporte.</p>'),
S('verify','8. Check the installation','8. Comprueba la instalación','<ol><li>Confirm there are no missing-dependency or database errors in the server console.</li><li>Give yourself one installed speaker item using your inventory tools.</li><li>Use the item, aim at a flat surface and press <kbd>E</kbd> to place it.</li><li>Open the speaker, search for a song and start playback.</li><li>Move away to check spatial audio, then open <code>/boomboxadmin</code> to confirm access.</li></ol><p>If a step fails, use <a href="#troubleshooting">troubleshooting</a>.</p>','<ol><li>Comprueba que no haya errores de dependencias o base de datos en la consola.</li><li>Date un ítem de speaker con las herramientas de tu inventario.</li><li>Úsalo, apunta a una superficie plana y pulsa <kbd>E</kbd> para colocarlo.</li><li>Abre el speaker, busca una canción y reprodúcela.</li><li>Aléjate para comprobar el audio espacial y abre <code>/boomboxadmin</code> para comprobar el acceso.</li></ol><p>Si falla algún paso, consulta <a href="#troubleshooting">solución de problemas</a>.</p>')]),
page('inventory','box','start','Inventory items','Ítems del inventario','One item for each speaker model. Use the definitions that match your inventory.','Un ítem por cada modelo. Usa las definiciones que correspondan a tu inventario.',[
S('adapter','Choose your inventory','Elige tu inventario',inventoryTabs,inventoryTabs),
S('icons','Inventory icons','Iconos del inventario',`<p>All nine icons are included as transparent PNGs. Preserve the filenames so they match the item definitions.</p>${D('inventory-images.zip','Download all inventory icons')}`,`<p>Los nueve iconos están incluidos en PNG transparente. Conserva los nombres para que coincidan con las definiciones.</p>${D('inventory-images.zip','Descargar todos los iconos')}`),
S('identifiers','Item identifiers','Identificadores',inventoryTables('en'),inventoryTables('es')),
S('custom','Custom names and providers','Nombres y proveedores personalizados','<p>The public <code>BlastBB.InventoryItems</code> settings control the RadioCar identifier and legacy speaker aliases. If you change identifiers, update your inventory definitions and migrate existing items in player inventories and stashes.</p><p>For unsupported inventories, implement the public <a href="#integrations">custom inventory bridge</a>. Automatic detection does not create item definitions on inventories without a registration API.</p>','<p>Los ajustes públicos de <code>BlastBB.InventoryItems</code> controlan el identificador de RadioCar y los alias de speakers antiguos. Si cambias identificadores, actualiza las definiciones y migra los objetos existentes en jugadores y almacenes.</p><p>Para otros inventarios, implementa el <a href="#integrations">bridge personalizado</a>. La detección automática no crea definiciones en inventarios que carecen de API de registro.</p>')]),
page('speakers','speaker','features','Speakers & placement','Speakers y colocación','Pick a model, place it in the world and use its own animated features.','Elige un modelo, colócalo en el mundo y usa sus funciones animadas.',[
S('models','The speaker collection','Los modelos',cards('en'),cards('es')),
S('placement','Place a speaker','Coloca un speaker','<p>Use a speaker item to open its hologram preview. Aim at a clear, nearby flat surface, including the top of a table. An invalid preview cannot be confirmed.</p>'+T(['Control','Action'],[['<kbd>E</kbd>','Confirm placement'],['<kbd>Backspace</kbd>','Cancel without placing'],['Mouse wheel / <kbd>←</kbd> <kbd>→</kbd>','Rotate the preview'],['<kbd>Shift</kbd> + rotation','Rotate faster']])+'<p>The item is removed after the placement is accepted by the server. The cooler preview is closed; opening it is a separate interaction after placement.</p>','<p>Usa un ítem de speaker para abrir la vista previa holográfica. Apunta a una superficie plana, cercana y libre, como una mesa. Una vista previa inválida no puede confirmarse.</p>'+T(['Control','Acción'],[['<kbd>E</kbd>','Confirmar colocación'],['<kbd>Retroceso</kbd>','Cancelar sin colocar'],['Rueda / <kbd>←</kbd> <kbd>→</kbd>','Girar la vista previa'],['<kbd>Shift</kbd> + giro','Girar más rápido']])+'<p>El ítem se retira al aceptar el servidor la colocación. La vista previa de la neverita está cerrada; abrirla es una acción posterior.</p>'),
S('interaction','Interact with a placed speaker','Interactúa con un speaker','<p>With the included 3D target, approach the speaker, navigate its available options with the wheel or arrow keys and press <kbd>E</kbd>. External targets use their own controls.</p><p>Open the player, retrieve the item or use model-specific actions such as the cooler lid, flower petals or event tripod. Available actions depend on permissions and the current model state.</p>','<p>Con el target 3D incluido, acércate al speaker, recorre las opciones con la rueda o las flechas y pulsa <kbd>E</kbd>. Los targets externos usan sus propios controles.</p><p>Abre el reproductor, recoge el ítem o usa acciones del modelo, como la tapa, los pétalos o el trípode. Las acciones disponibles dependen de los permisos y del estado actual.</p>'),
S('carrying','Carry a speaker','Transporta un speaker','<p>Place and configure the speaker first, then use its carry or equip action. The backpack is placed first too; equipping it is optional. World lyrics and the target are hidden while a speaker is carried.</p><p>Only the backpack is intended to remain equipped in a vehicle. Other handheld portables return to the inventory when entering; if they cannot fit, they are placed on the ground. Press the drop key to deliberately put down an equipped backpack or portable.</p><p>Fold the event speaker tripod before transporting it. Carrying a speaker disables melee attacks.</p>','<p>Coloca y configura el speaker y después usa la opción de transportar o equipar. La mochila también se coloca primero; ponértela es opcional. Las letras del mundo y el target se ocultan mientras lo llevas.</p><p>Solo la mochila está pensada para permanecer equipada en un vehículo. Los demás portátiles vuelven al inventario al subir; si no caben, se dejan en el suelo. Pulsa la tecla de soltar para bajar voluntariamente la mochila o el portátil.</p><p>Pliega el trípode del speaker de eventos antes de transportarlo. Llevar un speaker bloquea los golpes.</p>'),
S('colors','Colors and illumination','Colores e iluminación','<p>Body and detail colors can be changed in device settings when the administrator allows it. Default colors and permission to customize belong to the admin panel. The interface accent is administrator-controlled.</p>','<p>Los colores de carcasa y detalles pueden cambiarse en los ajustes del dispositivo si el administrador lo permite. Los colores iniciales y el permiso de personalización se controlan en el panel. El color de la interfaz es exclusivo del administrador.</p>')]),
page('music','music','features','Music, lyrics & playlists','Música, letras y playlists','Search from the player, organize the next songs and keep your favorite tracks together.','Busca desde el reproductor, organiza las próximas canciones y guarda tus favoritas.',[
S('search','Search and play','Buscar y reproducir','<p>Search by song or artist directly in the interface. Choose a result to start playback; copying a link is not necessary. Music catalog artwork is shown when available.</p><p>The search catalog and the playable video are separate: a track can appear in search even if its video is removed, restricted or unavailable.</p>','<p>Busca una canción o artista desde la interfaz. Elige un resultado para reproducirlo; no hace falta copiar un enlace. Se muestra la portada del catálogo musical cuando está disponible.</p><p>El catálogo y el vídeo reproducible son distintos: una canción puede aparecer aunque su vídeo esté retirado, restringido o no disponible.</p>'),
S('lyrics','Synchronized lyrics','Letras sincronizadas','<p>Open the expanded player to display synchronized lyrics when the selected track has them. Timing and word-level detail depend on the provider data available for that song.</p><p>World lyrics are a separate device option and must be allowed by the administrator. They are hidden while carrying a speaker.</p>'+N('Some songs have no lyrics','Missing lyrics do not prevent playback. Try another recording if the text or timing does not match.'),' <p>Abre el reproductor ampliado para ver las letras sincronizadas cuando la canción las tenga. La precisión y el detalle por palabra dependen de los datos disponibles.</p><p>Las letras del mundo son una opción separada del dispositivo y requieren autorización del administrador. Se ocultan mientras transportas un speaker.</p>'+N('Algunas canciones no tienen letras','La falta de letras no impide la reproducción. Prueba otra grabación si el texto o la sincronización no coinciden.')),
S('queue','The queue','La cola','<p>Add songs to the queue and drag entries to change their order. The automatic continuation system looks for related music to refill the queue as playback progresses, so a playlist is not required to continue listening.</p><p>Pause, stop, unavailable videos or failed network requests can interrupt playback. Automatic continuation depends on finding a playable next track.</p>','<p>Añade canciones a la cola y arrástralas para cambiar el orden. La continuación automática busca música relacionada para rellenarla mientras se reproduce, sin exigir una playlist.</p><p>Una pausa, una parada, vídeos no disponibles o fallos de red pueden interrumpir la música. La continuación depende de encontrar una siguiente canción reproducible.</p>'),
S('playlists','Create and customize playlists','Crear y personalizar playlists','<p>From a song\'s detail view, save it to a playlist or create one. Open the playlist library to inspect its songs, edit its details and set a custom cover image.</p><p>Playlists belong to the player identity selected by the bridge and are stored in the database. Use an accessible image URL for a custom cover; the player\'s browser must be able to load it.</p>','<p>Desde los detalles de una canción, guárdala en una playlist o crea una. Abre la biblioteca para ver las canciones, editar los detalles y poner una portada personalizada.</p><p>Las playlists se guardan en la base de datos y pertenecen a la identidad seleccionada por el bridge. Usa una URL accesible para la portada; el navegador del jugador debe poder cargarla.</p>')]),
page('channels','layers','features','Synchronized channels','Canales sincronizados','Connect placed speakers with a shared frequency and control one synchronized music session.','Conecta speakers con una frecuencia compartida y controla una sesión de música sincronizada.',[
S('connect','Join a frequency','Unirse a una frecuencia','<p>In each speaker\'s settings, enter the same frequency from <strong>1 to 9999</strong>. Frequency <strong>0</strong> makes the device independent. A joining speaker adopts the channel\'s song, playback position and pause state.</p>','<p>En los ajustes de cada speaker, introduce la misma frecuencia de <strong>1 a 9999</strong>. La frecuencia <strong>0</strong> deja el dispositivo independiente. Al entrar, el speaker adopta la canción, posición y pausa del canal.</p>'),
S('shared','What is shared','Qué se comparte','<p>Song, queue, shuffle, loop, pause and skips are shared. Each speaker keeps its own volume, range and visual settings. Device permissions still apply: an authorized controller of a connected speaker can control the shared session.</p><p>Each client plays one audio source per channel, transitioning between devices based on distance and volume.</p>','<p>Se comparten canción, cola, aleatorio, bucle, pausa y saltos. Cada speaker conserva volumen, alcance y apariencia. Los permisos siguen vigentes: alguien autorizado en un speaker conectado puede controlar la sesión compartida.</p><p>Cada cliente reproduce una fuente por canal y cambia entre dispositivos según distancia y volumen.</p>'),
S('leave','Leave and end a channel','Salir y terminar un canal','<p>Set the frequency to 0 to disconnect a speaker. It keeps its current song and playback position. Picking up one device does not stop the others.</p><p>The session ends when no connected devices remain and is not saved across resource restarts. RadioCar does not join speaker channels. Video buffering can cause temporary timing differences between clients.</p>','<p>Pon la frecuencia en 0 para desconectarlo. Conserva la canción y su posición. Recoger un equipo no detiene los restantes.</p><p>La sesión termina cuando no quedan equipos conectados y no se guarda al reiniciar. RadioCar no se conecta a estos canales. El buffering puede producir diferencias temporales entre jugadores.</p>')]),
page('radiocar','car','features','RadioCar','RadioCar','Install music in a vehicle, control it from the HUD and hear it change as you move around the car.','Instala música en un vehículo, contrólala desde el HUD y escucha cómo cambia al moverte alrededor.',[
S('install','Install from inside the vehicle','Instalar desde el vehículo','<ol><li>Enter an allowed vehicle with a <code>radiocar</code> item.</li><li>Use the item while seated. The server validates the installation.</li><li>Open the player and start a song. The default command is <code>/radiocar</code>.</li></ol><p>The GTA radio is disabled while using the installed RadioCar, avoiding overlapping stations.</p>','<ol><li>Sube a un vehículo permitido con el ítem <code>radiocar</code>.</li><li>Usa el objeto sentado dentro. El servidor valida la instalación.</li><li>Abre el reproductor y pon una canción. El comando inicial es <code>/radiocar</code>.</li></ol><p>La radio de GTA se desactiva al usar RadioCar para evitar que suenen dos emisoras.</p>'),
S('sound','Spatial vehicle audio','Audio espacial del vehículo','<p>Listen inside, then step outside and open a door or window to hear the change. Distance, obstacles and the vehicle\'s open/closed state affect the exterior sound. Administrators adjust the exterior closed gain and vehicle range.</p>','<p>Escucha dentro, sal y abre una puerta o ventanilla para notar el cambio. La distancia, los obstáculos y el estado abierto o cerrado afectan al sonido exterior. El administrador configura la ganancia con el coche cerrado y el alcance.</p>'),
S('hud','HUD and controls','HUD y controles','<p>Open the player to move the vehicle HUD or hide it with the visibility control. Personal HUD position and visibility preferences are saved.</p><p>Use <kbd>←</kbd> and <kbd>→</kbd> to change tracks; <kbd>↑</kbd> and <kbd>↓</kbd> adjust the volume when you are authorized to control the radio. Bindings can be changed in FiveM settings.</p>','<p>Abre el reproductor para mover el HUD del vehículo u ocultarlo con el control de visibilidad. Se guardan tus preferencias de posición y visibilidad.</p><p>Usa <kbd>←</kbd> y <kbd>→</kbd> para cambiar de canción; <kbd>↑</kbd> y <kbd>↓</kbd> ajustan el volumen si tienes autorización. Puedes reasignarlas en FiveM.</p>'),
S('restrictions','Vehicle restrictions','Restricciones de vehículos','<p>Under Admin → Vehicles, disable whole categories or add individual spawn model names such as <code>adder</code> or <code>police</code>. Custom models and numeric hashes are accepted.</p><p>The initial blocked categories are planes, helicopters, boats and submarines. Administrators can change the radio command and availability in the same section.</p>','<p>En Administración → Vehículos, bloquea categorías completas o añade nombres de aparición como <code>adder</code> o <code>police</code>. Se admiten modelos personalizados y hashes numéricos.</p><p>Las categorías bloqueadas inicialmente son aviones, helicópteros, barcos y submarinos. También puedes cambiar el comando y activar o desactivar RadioCar.</p>')]),
page('admin','shield','server','Admin panel','Panel de administrador','Manage devices and configure your server from one in-game panel. Open it with /boomboxadmin.','Gestiona dispositivos y configura el servidor desde un panel dentro del juego. Ábrelo con /boomboxadmin.',[
S('devices','Devices','Dispositivos','<p>Review speakers placed around the map. Locate, stop or remove a device, including devices whose owner is offline. Removal clears the placed device; it does not return an item to an offline owner.</p>','<p>Revisa los speakers colocados por la ciudad. Localiza, detén o retira equipos, incluso si su dueño está desconectado. La retirada elimina el dispositivo; no devuelve un ítem a un dueño desconectado.</p>'),
S('server','Server','Servidor','<p>Select the interface language, enable speakers, set per-player and server limits, and configure expiry for unused speakers. Reducing a placement limit does not remove existing devices.</p>','<p>Selecciona el idioma, activa los speakers, establece límites por jugador y servidor y configura la caducidad. Reducir un límite no elimina los equipos existentes.</p>'),
S('appearance','Appearance','Apariencia','<p>Set the default body and detail colors and decide whether players may recolor their own props. Change the interface accent for the entire server. Players cannot change the interface color.</p>','<p>Define los colores iniciales de carcasa y detalles y permite o bloquea la personalización de los props. Cambia el acento de la interfaz para todo el servidor. Los jugadores no pueden cambiar ese color.</p>'),
S('audio','Audio','Audio','<p>Set starting, minimum and maximum volume, the base speaker range and sound attenuation behind obstacles. Individual models apply their own audio profile to the base range.</p>','<p>Ajusta el volumen inicial, mínimo y máximo, el alcance base y la atenuación detrás de obstáculos. Cada modelo aplica su perfil al alcance base.</p>'),
S('interaction','Interaction','Interacción','<p>Set the interaction distance, the distance at which the 3D target becomes visible and the maximum placement distance. Target adapter selection belongs in <code>config.lua</code>.</p>','<p>Configura la distancia de interacción, de visibilidad del target 3D y de colocación. El adaptador de target se elige en <code>config.lua</code>.</p>'),
S('vehicles','Vehicles','Vehículos','<p>Enable RadioCar, change its command, configure range and closed-car exterior gain, and block categories or individual models.</p>','<p>Activa RadioCar, cambia su comando, configura alcance y sonido exterior con el coche cerrado y bloquea categorías o modelos.</p>'),
S('lyrics','Lyrics','Letras','<p>Allow or disable world lyrics for speakers and vehicles independently. Disabling a category removes the corresponding option from the player\'s device settings. Vehicle world lyrics start disabled for the device even when the server permits them.</p>','<p>Permite o desactiva las letras del mundo para speakers y vehículos por separado. Al desactivar una categoría, se quita esa opción de los ajustes del jugador. Las letras del vehículo comienzan apagadas en el equipo aunque el servidor las permita.</p>'),
S('webhooks','Webhooks','Webhooks','<p>Set separate Discord destinations for administration, devices, RadioCar, playback and errors. Empty destinations disable that activity log. Support telemetry has its own controls in <code>config.lua</code>; see <a href="#logging">logging and privacy</a>.</p>','<p>Configura destinos de Discord para administración, dispositivos, RadioCar, reproducción y errores. Un destino vacío desactiva ese registro. La telemetría de soporte se controla por separado en <code>config.lua</code>; consulta <a href="#logging">registros y privacidad</a>.</p>')]),
page('configuration','settings','server','Configuration','Configuración','Use config.lua for installation. Make everyday server changes from the admin panel.','Usa config.lua para instalar. Haz los cambios habituales desde el panel de administrador.',[
S('integrations','Inventory and target adapters','Adaptadores de inventario y target',`${C(cfg)}<p><code>Inventory</code>: <code>auto</code>, <code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code>, <code>esx</code> or <code>custom</code>. Auto prioritizes Quasar, Ox, QB and native ESX in that order.</p><p><code>Target</code>: <code>blast_3d</code>, <code>ox_target</code>, <code>qb-target</code>, <code>auto</code> or <code>none</code>. Choose <code>blast_3d</code> for the embedded target. An external target stopping falls back to the included target.</p><p>Use resource-name overrides only for renamed resources with compatible APIs. Restart Blast after editing installation settings.</p>`,`${C(cfg)}<p><code>Inventory</code>: <code>auto</code>, <code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code>, <code>esx</code> o <code>custom</code>. Auto prioriza Quasar, Ox, QB y ESX nativo, en ese orden.</p><p><code>Target</code>: <code>blast_3d</code>, <code>ox_target</code>, <code>qb-target</code>, <code>auto</code> o <code>none</code>. Elige <code>blast_3d</code> para el integrado. Si se detiene un target externo, se usa el incluido.</p><p>Usa los overrides de nombre solo para recursos renombrados con API compatible. Reinicia Blast al editar estos ajustes.</p>`),
S('permissions','Administrator permissions','Permisos de administrador',`${C(`BlastBB.Permissions = {
    AdminAces = { 'blast_boombox.admin' },
}`)}${C('add_ace group.manager blast_boombox.admin allow','SERVER.CFG')}<p>Any ACE in <code>AdminAces</code> grants access. The group in server.cfg must contain your player. Permission is checked server-side for every admin action.</p><p>For framework roles or custom permissions, edit <code>BlastBridge.CanAdmin(player, action)</code> in <code>bridge/permissions.lua</code>. Return true only for authorized players. Actions include open, save, language, locate, stop, remove and uninstall.</p>`,`${C(`BlastBB.Permissions = {
    AdminAces = { 'blast_boombox.admin' },
}`)}${C('add_ace group.manager blast_boombox.admin allow','SERVER.CFG')}<p>Cualquier ACE de <code>AdminAces</code> concede acceso. El grupo debe incluir a tu jugador. Cada acción administrativa vuelve a comprobar el permiso en el servidor.</p><p>Para roles de framework o permisos personalizados, edita <code>BlastBridge.CanAdmin(player, action)</code> en <code>bridge/permissions.lua</code>. Devuelve true solo para autorizados. Las acciones incluyen open, save, language, locate, stop, remove y uninstall.</p>`),
S('identity','Player identity','Identidad del jugador','<p>The bridge uses the FiveM license for player profiles by default. A custom <code>PlayerIdentifier</code> can make data character-specific, but changing identity rules requires migrating existing records.</p>','<p>El bridge utiliza la licencia de FiveM para los perfiles. Un <code>PlayerIdentifier</code> personalizado puede separar datos por personaje, pero cambiar la identidad requiere migrar los registros existentes.</p>'),
S('runtime','Saved server settings','Ajustes guardados','<p>Use <code>/boomboxadmin</code> for languages, limits, appearance, audio, interactions, vehicles and world lyrics. Saved database settings survive restarts and override initial defaults.</p>'+N('Avoid resetting the settings table casually','Removing it resets the server settings. Back up your database before intentional resets or migrations.'),' <p>Usa <code>/boomboxadmin</code> para idioma, límites, apariencia, audio, interacción, vehículos y letras del mundo. Los ajustes de base de datos sobreviven a los reinicios y tienen prioridad sobre los valores iniciales.</p>'+N('No borres los ajustes sin preparar una copia','Eliminar esa tabla reinicia la configuración. Guarda una copia de la base antes de un restablecimiento o una migración.'))]),
page('controls','keyboard','features','Controls & commands','Controles y comandos','Default bindings can be reassigned in GTA/FiveM settings. Existing player bindings are preserved.','Puedes reasignar las teclas en GTA/FiveM. Se conservan las asignaciones previas del jugador.',[
S('bindings','Default bindings','Teclas iniciales',T(['Context','Key','Action'],[['Placement','<kbd>E</kbd>','Place'],['Placement','<kbd>Backspace</kbd>','Cancel'],['Placement','Wheel / <kbd>←</kbd> <kbd>→</kbd>','Rotate; hold Shift for faster rotation'],['Built-in target','Wheel / arrows + <kbd>E</kbd>','Select and activate an option'],['Carried portable','<kbd>K</kbd>','Open player'],['Carried speaker','<kbd>N</kbd>','Put down'],['Authorized portable / RadioCar','<kbd>←</kbd> / <kbd>→</kbd>','Previous / next track'],['Authorized portable / RadioCar','<kbd>↑</kbd> / <kbd>↓</kbd>','Volume up / down']]),T(['Contexto','Tecla','Acción'],[['Colocación','<kbd>E</kbd>','Colocar'],['Colocación','<kbd>Retroceso</kbd>','Cancelar'],['Colocación','Rueda / <kbd>←</kbd> <kbd>→</kbd>','Girar; Shift para girar más rápido'],['Target integrado','Rueda / flechas + <kbd>E</kbd>','Seleccionar y activar'],['Portátil equipado','<kbd>K</kbd>','Abrir reproductor'],['Speaker transportado','<kbd>N</kbd>','Dejar en el suelo'],['Portátil / RadioCar autorizado','<kbd>←</kbd> / <kbd>→</kbd>','Anterior / siguiente'],['Portátil / RadioCar autorizado','<kbd>↑</kbd> / <kbd>↓</kbd>','Subir / bajar volumen']])),
S('commands','Commands','Comandos',T(['Command','Where','Purpose'],[['<code>/boomboxadmin</code>','In game','Open administration; requires permission.'],['<code>/radiocar</code>','In game','Open the installed vehicle radio; command can be changed in admin.'],['<code>boombox_telemetry status</code>','Server console','Inspect support-report state.'],['<code>boombox_telemetry send</code>','Server console','Request a report; 15-second manual cooldown.']]),T(['Comando','Dónde','Función'],[['<code>/boomboxadmin</code>','Juego','Abrir administración; requiere permiso.'],['<code>/radiocar</code>','Juego','Abrir la radio instalada; configurable en el panel.'],['<code>boombox_telemetry status</code>','Consola del servidor','Consultar estado de informes.'],['<code>boombox_telemetry send</code>','Consola del servidor','Solicitar informe; espera manual de 15 segundos.']])),
S('rebind','Change a binding','Reasignar una tecla','<p>Open Settings → Key Bindings → FiveM and locate the Boombox entries. FiveM saves each player\'s choices. A resource restart does not overwrite them.</p><p>If an old installation still uses G to drop a speaker, change that binding manually. Avoid conflicts with radial menus or other scripts using the same keys.</p>','<p>Abre Ajustes → Asignación de teclas → FiveM y busca las entradas de Boombox. FiveM guarda las preferencias del jugador. Reiniciar el recurso no las reemplaza.</p><p>Si una instalación antigua sigue usando G para soltar, cambia la tecla manualmente. Evita conflictos con menús radiales u otros scripts.</p>')]),
page('persistence','database','server','Persistence & updates','Persistencia y actualizaciones','Know what survives a restart and how to update an existing installation.','Qué se conserva al reiniciar y cómo actualizar una instalación.',[
S('tables','Automatically created tables','Tablas automáticas',T(['Table','Stores'],[['<code>blast_boombox_settings</code>','Server settings'],['<code>blast_boombox_playlists</code>','Player playlists'],['<code>blast_boombox_placed</code>','Placed devices'],['<code>blast_boombox_radiocars</code>','Vehicle installations'],['<code>blast_boombox_radio_profiles</code>','Vehicle radio profiles'],['<code>blast_boombox_ui_positions</code>','Player interface positions'],['<code>blast_boombox_hud_preferences</code>','HUD preferences']]),T(['Tabla','Datos'],[['<code>blast_boombox_settings</code>','Configuración del servidor'],['<code>blast_boombox_playlists</code>','Playlists de jugadores'],['<code>blast_boombox_placed</code>','Dispositivos colocados'],['<code>blast_boombox_radiocars</code>','Instalaciones en vehículos'],['<code>blast_boombox_radio_profiles</code>','Perfiles de radio'],['<code>blast_boombox_ui_positions</code>','Posición de interfaces'],['<code>blast_boombox_hud_preferences</code>','Preferencias del HUD']])),
S('restore','Speaker restoration','Restauración de speakers','<p>Placed speakers retain owner, position, orientation, model, colors, LEDs, volume, frequency, privacy, shared permissions and world-lyrics preferences. They are restored when the resource starts without automatically starting music.</p><p>If the resource restarts while a speaker is carried, it returns to its last saved ground position. Live channel sessions are not persisted.</p>','<p>Se conservan dueño, posición, orientación, modelo, colores, LEDs, volumen, frecuencia, privacidad, permisos compartidos y letras del mundo. Los speakers se restauran al iniciar sin arrancar música automáticamente.</p><p>Si el recurso se reinicia mientras lo llevas, vuelve a la última posición guardada en el suelo. Las sesiones activas de canal no se guardan.</p>'),
S('expiry','Unused speaker expiry','Caducidad de speakers','<p>The initial expiry is 7 days without use. Set it to <strong>0</strong> in the admin panel to disable expiry. Active playing or carried speakers do not expire while active. Retrieving a speaker returns its item and removes its placement record.</p>','<p>La caducidad inicial es de 7 días sin uso. Pon <strong>0</strong> en el panel para desactivarla. Los speakers que reproducen o se transportan no caducan mientras estén activos. Recoger uno devuelve su ítem y elimina el registro.</p>'),
S('updates','Update safely','Actualizar','<ol><li>Back up the database and public configuration/bridge changes.</li><li>Follow the release instructions and replace the product files.</li><li>Merge new item definitions if the release adds models.</li><li>Restart affected dependencies, then run <code>refresh</code> and <code>ensure blast_boombox</code>.</li><li>Check startup, a placed speaker, playlists and RadioCar.</li></ol><p>Do not drop the tables as part of a normal update.</p>','<ol><li>Guarda la base de datos y tus cambios de configuración o bridge.</li><li>Sigue las instrucciones de la versión y sustituye los archivos.</li><li>Añade nuevas definiciones si se incluyen más modelos.</li><li>Reinicia las dependencias afectadas y ejecuta <code>refresh</code> y <code>ensure blast_boombox</code>.</li><li>Comprueba inicio, speakers, playlists y RadioCar.</li></ol><p>No borres las tablas para una actualización normal.</p>')]),
page('logging','activity','server','Logging & privacy','Registros y privacidad','Configure your activity logs and choose whether to send aggregate support reports.','Configura los registros de actividad y decide si envías informes agregados de soporte.',[
S('activity','Administrator activity webhooks','Webhooks de actividad','<p>Open Admin → Webhooks. Set separate Discord webhook URLs for administrative changes, device placement/removal, RadioCar installations, playback and playback errors. Leave a destination blank to disable its logs.</p><p>Destinations are handled on the server. Do not share webhook tokens when requesting support.</p>','<p>Abre Administración → Webhooks. Configura URLs de Discord para cambios administrativos, colocación o retirada, RadioCar, reproducción y errores. Deja un destino vacío para desactivarlo.</p><p>Los destinos se manejan en el servidor. No compartas los tokens al pedir soporte.</p>'),
S('support','Aggregate support reports','Informes agregados de soporte','<p>Support telemetry is separate from your activity webhooks. It sends installation ID, version, detected integrations, device counts, model distribution, uptime, usage counters and fixed failure counters to Blast.</p><p>It does not include player identities/IPs, music history, coordinates, plates, searches, database contents or credentials. The current source configuration enables reports and server identity; inspect the two flags below for your installation.</p>','<p>La telemetría es independiente de tus webhooks. Envía a Blast un ID de instalación, versión, integraciones, cantidad de equipos, distribución de modelos, tiempo activo y contadores de uso y fallos.</p><p>No incluye identidades o IP de jugadores, historial musical, coordenadas, matrículas, búsquedas, contenido de la base ni credenciales. La configuración fuente actual activa los informes y la identidad del servidor; revisa ambos ajustes.</p>'),
S('disable','Disable reports or server identity','Desactivar informes o identidad',`<p>Edit <code>config.lua</code> and restart the resource. This example disables all support reports:</p>${C(telemetry)}<p><code>Enabled = false</code> stops new support reports and counter collection. With reports enabled, <code>SendServerIdentity = false</code> omits the server name and public address and skips the address lookup.</p><p>When enabled, identity is detected automatically from the server name and outbound public IP. That IP may differ from the game address behind NAT or a proxy. Disabling reports does not erase reports already sent.</p>`,`<p>Edita <code>config.lua</code> y reinicia. Este ejemplo desactiva todos los informes:</p>${C(telemetry)}<p><code>Enabled = false</code> detiene los informes y los nuevos contadores. Si mantienes informes activos, <code>SendServerIdentity = false</code> omite nombre y dirección pública y evita consultar la IP.</p><p>La identidad se obtiene automáticamente del nombre del servidor y la IP pública de salida, que puede diferir de la dirección de juego con NAT o proxy. Desactivarlo no borra los informes enviados anteriormente.</p>`),
S('diagnostics','Report diagnostics','Diagnóstico',`${C('boombox_telemetry status\nboombox_telemetry send','SERVER CONSOLE')}<p>The first scheduled report is approximately one minute after startup, then hourly. Delivery errors do not block music. Diagnostics do not print the destination URL.</p>`,`${C('boombox_telemetry status\nboombox_telemetry send','CONSOLA DEL SERVIDOR')}<p>El primer informe programado llega aproximadamente al minuto y los siguientes cada hora. Un error de entrega no bloquea la música. El diagnóstico no imprime la URL de destino.</p>`)]),
page('integrations','code','server','Custom integrations','Integraciones personalizadas','Connect another inventory using the public bridge and client exports.','Conecta otro inventario mediante el bridge público y los exports de cliente.',[
S('inventory','Inventory bridge','Bridge de inventario','<p>Select <code>Inventory = \'custom\'</code> and implement <code>CustomInventory</code> in <code>bridge/server.lua</code>. The initial custom functions reject operations until implemented.</p>'+T(['Function','Expected behavior'],[['<code>Count(player, name)</code>','Return the real server-side item count.'],['<code>GetItem(player, name, slot)</code>','Return item data with name/count/slot/metadata, or nil.'],['<code>Remove(player, name, count, metadata, slot)</code>','Return true only if the requested item quantity was removed.'],['<code>Add(player, name, count, metadata)</code>','Return true if added; false when the item cannot fit.']]),'<p>Selecciona <code>Inventory = \'custom\'</code> e implementa <code>CustomInventory</code> en <code>bridge/server.lua</code>. Las funciones iniciales rechazan operaciones hasta que las implementes.</p>'+T(['Función','Comportamiento'],[['<code>Count(player, name)</code>','Devolver la cantidad real del servidor.'],['<code>GetItem(player, name, slot)</code>','Devolver name/count/slot/metadata, o nil.'],['<code>Remove(player, name, count, metadata, slot)</code>','True solo al retirar la cantidad solicitada.'],['<code>Add(player, name, count, metadata)</code>','True si se añade; false si no cabe.']])),
S('exports','Client item exports','Exports de ítems en cliente',`${C(`exports.blast_boombox:useBoombox({
    name = 'portable_speaker',
    slot = itemSlot
})

exports.blast_boombox:useRadioCar({ slot = itemSlot })`,'CLIENT.LUA')}<p>Register usable items with your inventory API and call the appropriate client export. Do not consume an item in the registration handler; Blast validates and removes it when the action succeeds.</p>`,`${C(`exports.blast_boombox:useBoombox({
    name = 'portable_speaker',
    slot = itemSlot
})

exports.blast_boombox:useRadioCar({ slot = itemSlot })`,'CLIENT.LUA')}<p>Registra los utilizables con la API del inventario y llama al export de cliente correspondiente. No consumas el ítem en el manejador: Blast lo valida y lo retira cuando la acción termina correctamente.</p>`),
S('editable','Editable integration files','Archivos editables','<p>The public configuration and bridge files are excluded from Asset Escrow. Use <code>bridge/permissions.lua</code> for admin authorization and the inventory adapter for custom storage.</p><p>Validate quantities and metadata on the server. Renaming a provider is only supported when its API still matches the selected adapter.</p>','<p>La configuración y los archivos del bridge quedan fuera de Asset Escrow. Usa <code>bridge/permissions.lua</code> para autorizar administradores y el adaptador de inventario para proveedores personalizados.</p><p>Valida cantidades y metadatos en el servidor. Renombrar un proveedor solo funciona si su API coincide con el adaptador.</p>')]),
page('troubleshooting','tool','help','Troubleshooting','Solución de problemas','Start with the server console and client F8. Match the symptom before changing settings.','Empieza por la consola del servidor y F8. Identifica el síntoma antes de cambiar ajustes.',[
S('startup','The resource does not start','El recurso no inicia','<p>Check that ox_lib and oxmysql start before Blast, the folder is named <code>blast_boombox</code> and all product files are present. For SQL failures, check the connection and database permissions.</p><p>A Lua parse error or missing JavaScript global indicates a broken or incomplete build. Restore a complete matching release rather than editing obfuscated product files.</p>','<p>Comprueba que ox_lib y oxmysql inicien antes, que la carpeta se llame <code>blast_boombox</code> y que estén todos los archivos. Para errores SQL, revisa conexión y permisos.</p><p>Un error de sintaxis Lua o una variable JavaScript ausente indica una versión dañada o incompleta. Instala una distribución completa de la misma versión.</p>'),
S('items','Items are missing or unusable','Faltan ítems o no funcionan','<p>Confirm the catalog entries were merged, icons match their filenames and the inventory was restarted. In ox_inventory, keep the client exports and <code>consume = 0</code>. Check the detected adapter in the console; force the correct one when multiple inventories are running.</p>','<p>Comprueba que se integraron las definiciones, que las imágenes coinciden y que se reinició el inventario. En ox_inventory, conserva los exports y <code>consume = 0</code>. Revisa el adaptador detectado; fija el correcto si hay varios inventarios.</p>'),
S('target','The target is missing','No aparece el target','<p>Check the target selection in config.lua. Use <code>blast_3d</code> for the included interface. Approach within the interaction distance; visibility distance alone does not allow actions. The target is intentionally hidden on carried speakers.</p>','<p>Revisa el target en config.lua. Usa <code>blast_3d</code> para el incluido. Acércate a la distancia de interacción; verlo no significa poder usarlo. Se oculta intencionalmente en speakers transportados.</p>'),
S('playback','Search works, but music does not','Busca, pero no reproduce','<p>Try another song or recording. Videos may disallow embedded playback or be unavailable in a region. Check the client console, network access and volume. A result in the catalog does not guarantee that its video can play.</p>','<p>Prueba otra canción o grabación. Algunos vídeos bloquean la reproducción integrada o no están disponibles en ciertas regiones. Revisa F8, la red y el volumen. Un resultado del catálogo no garantiza un vídeo reproducible.</p>'),
S('lyrics','Lyrics are missing or delayed','Letras ausentes o desfasadas','<p>Lyrics are only shown when synchronized data is available. Different recordings can have different timing. Check another result and confirm the administrator permits world lyrics if you are using the world display.</p>','<p>Las letras aparecen cuando hay datos sincronizados. Las distintas grabaciones pueden tener otro tiempo. Prueba otro resultado y comprueba el permiso de letras del mundo si usas esa pantalla.</p>'),
S('admin','Admin access is denied','Acceso de administrador denegado','<p>Check the ACE spelling, the configured AdminAces list and group membership. If you customized the permission bridge, confirm it returns true for the requested action. Saved language and appearance settings are in the database, so editing initial defaults does not overwrite them.</p>','<p>Revisa el nombre de la ACE, AdminAces y la pertenencia al grupo. Si personalizaste el bridge, comprueba que devuelve true para la acción. Los ajustes de idioma y apariencia están en la base; editar sus valores iniciales no los sobrescribe.</p>'),
S('support','What to include in a support request','Qué incluir al pedir soporte','<p>Include the product version, framework/inventory/target versions, exact reproduction steps, and relevant server/F8 error lines. Explain whether it happens with one song, one device or all devices.</p><p>Remove webhook tokens, database credentials, API keys and player identifiers before sharing logs. For documentation mistakes, use the GitHub issue link in the footer.</p>','<p>Indica versión del producto, framework, inventario y target; pasos exactos y líneas relevantes de consola o F8. Explica si ocurre con una canción, un dispositivo o todos.</p><p>Retira tokens de webhook, credenciales SQL, claves e identificadores de jugadores antes de compartir registros. Para errores de documentación, usa el enlace de GitHub del pie.</p>')]),
page('faq','help','help','Frequently asked questions','Preguntas frecuentes','Quick answers to common installation and usage questions.','Respuestas rápidas sobre instalación y uso.',[
S('questions','Common questions','Preguntas habituales',[
['Is it standalone?','Yes. The core needs ox_lib and oxmysql, but does not require ESX, QBCore or Qbox. Item workflows still need an inventory integration.'],['Do I need ox_target or blast_common?','No. Set Target to blast_3d to use the self-contained 3D target.'],['Do I need Python or a separate music-search resource?','No. The catalog engine is part of Blast Boombox.'],['Do I need to import SQL?','Blast data tables are created automatically. Older native ESX inventories may need the optional item-definition SQL.'],['Can players change the interface color?','No. The interface color is administrator-controlled. Administrators can separately allow player customization of prop colors.'],['Can the backpack play inside a vehicle?','It can stay equipped inside a vehicle. Other handheld portables return to inventory, or the ground if the inventory cannot accept them.'],['Does RadioCar join speaker frequencies?','No. Channels connect speakers; RadioCar has its own vehicle session.'],['Why does the language remain Spanish after editing defaults?','An existing settings database restores the language previously saved by the administrator. Change it in the admin panel.'],['Can I disable support reports?','Yes. Set BlastBB.Telemetry.Enabled to false in config.lua and restart. You can also omit server identity while keeping aggregate reports enabled.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join(''),[
['¿Es standalone?','Sí. El núcleo necesita ox_lib y oxmysql, pero no exige ESX, QBCore ni Qbox. Los flujos de ítems requieren integrar un inventario.'],['¿Necesita ox_target o blast_common?','No. Selecciona blast_3d en Target para usar el sistema 3D incluido.'],['¿Necesita Python o un recurso de búsqueda separado?','No. El motor de catálogo forma parte de Blast Boombox.'],['¿Debo importar SQL?','Las tablas de Blast se crean automáticamente. Las versiones antiguas de ESX nativo pueden necesitar el SQL opcional de ítems.'],['¿Los jugadores pueden cambiar el color de la interfaz?','No. Ese color es exclusivo del administrador. Puedes permitir por separado que personalicen los props.'],['¿La mochila puede sonar dentro de un vehículo?','Puede permanecer equipada. Los demás portátiles vuelven al inventario o al suelo si no caben.'],['¿RadioCar se conecta a las frecuencias de los speakers?','No. Los canales conectan speakers; RadioCar usa una sesión del vehículo.'],['¿Por qué sigue en español después de cambiar los valores iniciales?','Una base existente restaura el idioma guardado por el administrador. Cámbialo en el panel.'],['¿Puedo desactivar los informes de soporte?','Sí. Pon BlastBB.Telemetry.Enabled en false dentro de config.lua y reinicia. También puedes omitir la identidad manteniendo informes agregados.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join(''))])
];
window.DOCS.sort((a,b)=>['start','features','server','help'].indexOf(a.group)-['start','features','server','help'].indexOf(b.group));
})();
